// Count button presses with an interrupt; each press toggles the LED
const int BUTTON_PIN = 2;
const int LED_PIN = 13;
const unsigned long DEBOUNCE_MS = {{p:debounce}};

volatile bool pressed = false;
volatile unsigned long lastChange = 0;
int count = 0;
bool ledOn = false;

// runs on every edge of D2, even while loop() is busy
void onChange() {
  unsigned long now = millis();
  if (digitalRead(BUTTON_PIN) == LOW && now - lastChange > DEBOUNCE_MS) {
    pressed = true;
  }
  lastChange = now;
}

void setup() {
  Serial.begin(9600);
  pinMode(BUTTON_PIN, INPUT_PULLUP);   // released = HIGH, pressed = LOW
  pinMode(LED_PIN, OUTPUT);
  attachInterrupt(digitalPinToInterrupt(BUTTON_PIN), onChange, CHANGE);
}

void loop() {
  if (pressed) {
    pressed = false;
    count++;
    ledOn = !ledOn;
    digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
    Serial.print("presses: ");
    Serial.println(count);
  }
}

